class Account {
  #balance = 0;
  constructor(owner) { this.owner = owner; }
  deposit(amount) { if (amount <= 0) throw new Error('invalid amount'); this.#balance += amount; }
  get balance() { return this.#balance; }
}
const account = new Account('Sara');
account.deposit(100);
console.log(account.balance);
